begin;
do $$
declare admin_id uuid; manager_id uuid; branch uuid; product uuid; order_id uuid; line_id uuid; invoice_id uuid; stamp timestamptz; next_stamp timestamptz; denied boolean; day date:=(now() at time zone 'America/Toronto')::date;
begin
 select id into admin_id from public.profiles where role::text='CENTRAL_ADMIN' and status::text='active' limit 1;
 select id,location_id into manager_id,branch from public.profiles where role::text='BRANCH_MANAGER' and status::text='active' and location_id is not null limit 1;
 if admin_id is null or manager_id is null then raise exception 'Active admin and manager required.';end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 insert into public.catalog_items(name,category,unit_type,default_price,available_stock) values('Payment test (rolled back)','Pantry','Bucket',2,20) returning id into product;
 insert into public.orders(location_id,order_number,order_date) values(branch,-2147483050,day) returning id into order_id;
 insert into public.order_lines(order_id,item_id,quantity,fulfilled_quantity,unit_price,is_taxable,line_total) values(order_id,product,5,5,2,false,10) returning id into line_id;
 update public.orders set status='READY' where id=order_id;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);
 perform public.submit_pickup(order_id,jsonb_build_array(jsonb_build_object('line_id',line_id,'quantity',5)),'',false);
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 execute 'set local role authenticated';
 invoice_id:=public.create_weekly_invoice(branch,day,day,array[order_id]);
 perform public.send_weekly_invoice(invoice_id);
 if (select payment_status from public.weekly_invoices where id=invoice_id)<>'UNPAID' then raise exception 'New invoice should be unpaid';end if;
 stamp:=public.set_invoice_payment_status(invoice_id,'PAID',null);
 if not exists(select 1 from public.weekly_invoices where id=invoice_id and payment_status='PAID' and payment_revision=revision and payment_updated_by=admin_id and payment_updated_name is not null) then raise exception 'Payment status or actor missing';end if;
 denied:=false;begin perform public.set_invoice_payment_status(invoice_id,'UNPAID',null);exception when others then denied:=sqlerrm like '%changed%';end;if not denied then raise exception 'Stale payment update accepted';end if;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);
 if (select payment_status from public.weekly_invoices where id=invoice_id)<>'PAID' then raise exception 'Branch cannot view paid invoice';end if;
 denied:=false;begin perform public.set_invoice_payment_status(invoice_id,'UNPAID',stamp);exception when others then denied:=sqlerrm like '%Only an active central admin%';end;if not denied then raise exception 'Manager updated payment';end if;
 begin update public.weekly_invoices set payment_status='UNPAID' where id=invoice_id;exception when others then null;end;
 if (select payment_status from public.weekly_invoices where id=invoice_id)<>'PAID' then raise exception 'Direct branch write changed payment';end if;
 execute 'set local role postgres';
 update public.profiles set role='BRANCH_EMPLOYEE' where id=manager_id;
 execute 'set local role authenticated';
 if exists(select 1 from public.weekly_invoices where id=invoice_id) then raise exception 'Employee invoice access expanded';end if;
 denied:=false;begin perform public.set_invoice_payment_status(invoice_id,'UNPAID',stamp);exception when others then denied:=true;end;if not denied then raise exception 'Employee updated payment';end if;
 execute 'set local role postgres';
 update public.weekly_invoices set revision=revision+1 where id=invoice_id;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 execute 'set local role authenticated';
 if (select payment_revision>=revision from public.weekly_invoices where id=invoice_id) then raise exception 'Edited invoice lost payment review marker';end if;
 next_stamp:=public.set_invoice_payment_status(invoice_id,'PAID',stamp);
 if next_stamp=stamp or not exists(select 1 from public.weekly_invoices where id=invoice_id and payment_revision=revision) then raise exception 'Paid confirmation did not accept current revision';end if;
 perform public.set_invoice_payment_status(invoice_id,'UNPAID',next_stamp);
 if not exists(select 1 from public.weekly_invoices where id=invoice_id and payment_status='UNPAID' and payment_revision is null) then raise exception 'Unpaid update failed';end if;
 execute 'set local role postgres';
end;$$;
rollback;
select 'Passed: Unpaid/Paid, named admin update, branch read-only visibility, employee isolation, stale update protection and payment review after invoice revisions. Fixtures rolled back.' as result;
